mapper.select:
SELECT
    id, user_id, user_name, conversation_id, agent_id, agent_name,
    fenci_session_id, fenci_agent_id, fenci_agent_name,
    question, actual_question, split_words, answer, answer_all,
    permission, is_deep, is_good, answer_time,session_uuid,
    question_feedback, answer_feedback, opinion_feedback, remarks, descriptions, environment,  create_time, update_time
FROM ai_history_message
where 1=1

    and user_id = #{userId, jdbcType=VARCHAR}


    and user_name = #{userName, jdbcType=VARCHAR}


    and conversation_id = #{conversationId, jdbcType=VARCHAR}


    and agent_id = #{agentId, jdbcType=VARCHAR}


    and agent_name = #{agentName, jdbcType=VARCHAR}


    and fenci_session_id = #{fenciSessionId, jdbcType=VARCHAR}


    and fenci_agent_id = #{fenciAgentId, jdbcType=VARCHAR}


    and fenci_agent_name = #{fenciAgentName, jdbcType=VARCHAR}


    and question = #{question, jdbcType=VARCHAR}


    and actual_question = #{actualQuestion, jdbcType=VARCHAR}


    and split_words = #{splitWords, jdbcType=VARCHAR}


    and answer = #{answer, jdbcType=VARCHAR}


    and answer_all = #{answerAll, jdbcType=VARCHAR}


    and permission = #{permission, jdbcType=VARCHAR}


    and is_deep = #{isDeep, jdbcType=VARCHAR}


    and is_good = #{isGood, jdbcType=VARCHAR}


    and answer_time = #{answerTime, jdbcType=VARCHAR}


    and question_feedback = #{questionFeedback, jdbcType=VARCHAR}


    and answer_feedback = #{answerFeedback, jdbcType=VARCHAR}


    and opinion_feedback = #{opinionFeedback, jdbcType=VARCHAR}


    and remarks = #{remarks, jdbcType=VARCHAR}


    and descriptions = #{descriptions, jdbcType=VARCHAR}


    and environment = #{environment, jdbcType=VARCHAR}


    and session_uuid = #{sessionUuid, jdbcType=VARCHAR}

ORDER BY create_time
